function(container, apiUrl, tables) {
  // 業務ロジックモジュールをインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData, 
    collectWeatherData, 
    collectEventData, 
    collectSeasonalData, 
    analyzeCorrelationSalesWeather, 
    analyzeCorrelationSalesEvent, 
    analyzeCorrelationSalesSeason, 
    compareWithHistoricalData, 
    findAlternativeComparisonData, 
    validateComparisonPeriod 
  } = window.aivicLogic || {};

  let currentProducts = [];
  let selectedOrders = [];

  // テーブルインデックス
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const DEMAND_FORECAST_TABLE = 8; // 需要予測結果
  const ORDER_TABLE = 9; // 発注データ

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    if (errorDiv) {
      errorDiv.textContent = message;
      errorDiv.classList.remove('hidden');
      setTimeout(() => errorDiv.classList.add('hidden'), 5000);
    }
    window.aivicNotify?.error(message);
  }

  // 成功表示関数
  function showSuccess(message) {
    window.aivicNotify?.success(message);
  }

  // 日付バリデーション
  function validateDateRange() {
    const startDate = container.querySelector('#date-start')?.value;
    const endDate = container.querySelector('#date-end')?.value;

    if (startDate && endDate && startDate > endDate) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    // 業務ロジックでの期間バリデーション
    if (validateComparisonPeriod && startDate && endDate) {
      try {
        const isValid = validateComparisonPeriod(startDate, endDate);
        if (!isValid) {
          showError('指定された期間は無効です');
          return false;
        }
      } catch (error) {
        showError('期間バリデーションエラー: ' + error.message);
        return false;
      }
    }

    return true;
  }

  // 需要予測データを取得・分析
  async function getDemandForecast(productId, storeId, startDate, endDate) {
    try {
      // 売上データを収集
      const salesData = collectSalesData ? await collectSalesData(productId, storeId, startDate, endDate) : [];

      // 商品別に分類
      const productSalesData = classifySalesDataByProduct ? classifySalesDataByProduct(salesData) : salesData;

      // 有効な商品データをフィルタリング
      const validProductData = filterValidProductData ? filterValidProductData(productSalesData) : productSalesData;

      // 天候データを収集
      const weatherData = collectWeatherData ? await collectWeatherData(startDate, endDate) : [];

      // イベントデータを収集
      const eventData = collectEventData ? await collectEventData(startDate, endDate) : [];

      // 季節データを収集
      const seasonalData = collectSeasonalData ? collectSeasonalData(startDate, endDate) : [];

      // 相関分析
      let correlationResults = {};
      if (analyzeCorrelationSalesWeather) {
        correlationResults.weather = analyzeCorrelationSalesWeather(validProductData, weatherData);
      }
      if (analyzeCorrelationSalesEvent) {
        correlationResults.event = analyzeCorrelationSalesEvent(validProductData, eventData);
      }
      if (analyzeCorrelationSalesSeason) {
        correlationResults.seasonal = analyzeCorrelationSalesSeason(validProductData, seasonalData);
      }

      // 過去データとの比較
      const historicalComparison = compareWithHistoricalData ? 
        await compareWithHistoricalData(validProductData, startDate, endDate) : null;

      return {
        salesData: validProductData,
        weatherData,
        eventData,
        seasonalData,
        correlationResults,
        historicalComparison
      };
    } catch (error) {
      console.error('需要予測データ取得エラー:', error);
      throw error;
    }
  }

  // 発注データを読み込み
  async function loadOrderData() {
    try {
      const startDate = container.querySelector('#date-start')?.value;
      const endDate = container.querySelector('#date-end')?.value;
      const storeId = container.querySelector('#store-select')?.value;
      const productId = container.querySelector('#product-select')?.value;

      if (!validateDateRange()) return;

      // 需要予測データを取得
      const forecastData = await getDemandForecast(productId, storeId, startDate, endDate);

      // 発注データを取得
      const orderData = await window.aivicApi.list(ORDER_TABLE, {
        store_id: storeId,
        product_id: productId,
        order_date_from: startDate,
        order_date_to: endDate
      });

      // テーブルに表示
      displayOrderData(orderData, forecastData);
      showSuccess('発注データを読み込みました');

    } catch (error) {
      showError('発注データの読み込みに失敗しました: ' + error.message);
    }
  }

  // 発注データをテーブルに表示
  function displayOrderData(orderData, forecastData) {
    const tbody = container.querySelector('#order-table tbody');
    if (!tbody) return;

    tbody.innerHTML = '';

    orderData.forEach(order => {
      const row = document.createElement('tr');
      row.innerHTML = `
        <td><input type="checkbox" class="order-checkbox" data-order-id="${order.id}"></td>
        <td>${order.product_name || ''}</td>
        <td>${order.store_name || ''}</td>
        <td>${order.order_date || ''}</td>
        <td>${order.quantity || 0}</td>
        <td>${order.unit_price || 0}</td>
        <td>${(order.quantity * order.unit_price) || 0}</td>
        <td>${order.status || ''}</td>
        <td>
          <button class="edit-order-btn" data-order-id="${order.id}">編集</button>
          <button class="delete-order-btn" data-order-id="${order.id}">削除</button>
        </td>
      `;
      tbody.appendChild(row);
    });

    // チェックボックスのイベントリスナーを追加
    tbody.querySelectorAll('.order-checkbox').forEach(checkbox => {
      checkbox.addEventListener('change', updateSelectedOrders);
    });

    // 編集・削除ボタンのイベントリスナーを追加
    tbody.querySelectorAll('.edit-order-btn').forEach(btn => {
      btn.addEventListener('click', (e) => editOrder(e.target.dataset.orderId));
    });

    tbody.querySelectorAll('.delete-order-btn').forEach(btn => {
      btn.addEventListener('click', (e) => deleteOrder(e.target.dataset.orderId));
    });
  }

  // 選択された発注を更新
  function updateSelectedOrders() {
    const checkboxes = container.querySelectorAll('.order-checkbox:checked');
    selectedOrders = Array.from(checkboxes).map(cb => cb.dataset.orderId);

    // 一括操作ボタンの有効/無効を切り替え
    const bulkButtons = container.querySelectorAll('.bulk-action-btn');
    bulkButtons.forEach(btn => {
      btn.disabled = selectedOrders.length === 0;
    });
  }

  // 新規発注作成
  async function createOrder() {
    try {
      const productId = container.querySelector('#product-select')?.value;
      const storeId = container.querySelector('#store-select')?.value;
      const quantity = container.querySelector('#order-quantity')?.value;
      const orderDate = container.querySelector('#order-date')?.value;

      if (!productId || !storeId || !quantity || !orderDate) {
        showError('必須項目を入力してください');
        return;
      }

      // 商品情報を取得
      const product = await window.aivicApi.get(PRODUCTS_TABLE, productId);

      const orderData = {
        product_id: productId,
        store_id: storeId,
        quantity: parseInt(quantity),
        unit_price: product.price || 0,
        order_date: orderDate,
        status: '未処理'
      };

      await window.aivicApi.save(ORDER_TABLE, orderData);
      showSuccess('発注を作成しました');

      // データを再読み込み
      await loadOrderData();

      // フォームをクリア
      container.querySelector('#order-quantity').value = '';
      container.querySelector('#order-date').value = '';

    } catch (error) {
      showError('発注の作成に失敗しました: ' + error.message);
    }
  }

  // 発注編集
  async function editOrder(orderId) {
    try {
      const order = await window.aivicApi.get(ORDER_TABLE, orderId);

      // 編集フォームに値を設定
      container.querySelector('#product-select').value = order.product_id || '';
      container.querySelector('#store-select').value = order.store_id || '';
      container.querySelector('#order-quantity').value = order.quantity || '';
      container.querySelector('#order-date').value = order.order_date || '';

      // 編集モードに切り替え
      const createBtn = container.querySelector('#create-order-btn');
      const updateBtn = container.querySelector('#update-order-btn');
      const cancelBtn = container.querySelector('#cancel-edit-btn');

      if (createBtn) createBtn.style.display = 'none';
      if (updateBtn) {
        updateBtn.style.display = 'inline-block';
        updateBtn.dataset.orderId = orderId;
      }
      if (cancelBtn) cancelBtn.style.display = 'inline-block';

    } catch (error) {
      showError('発注データの取得に失敗しました: ' + error.message);
    }
  }

  // 発注更新
  async function updateOrder() {
    try {
      const updateBtn = container.querySelector('#update-order-btn');
      const orderId = updateBtn?.dataset.orderId;

      if (!orderId) {
        showError('更新対象の発注が選択されていません');
        return;
      }

      const productId = container.querySelector('#product-select')?.value;
      const storeId = container.querySelector('#store-select')?.value;
      const quantity = container.querySelector('#order-quantity')?.value;
      const orderDate = container.querySelector('#order-date')?.value;

      if (!productId || !storeId || !quantity || !orderDate) {
        showError('必須項目を入力してください');
        return;
      }

      // 商品情報を取得
      const product = await window.aivicApi.get(PRODUCTS_TABLE, productId);

      const orderData = {
        id: orderId,
        product_id: productId,
        store_id: storeId,
        quantity: parseInt(quantity),
        unit_price: product.price || 0,
        order_date: orderDate
      };

      await window.aivicApi.update(ORDER_TABLE, orderData);
      showSuccess('発注を更新しました');

      // 編集モードを終了
      cancelEdit();

      // データを再読み込み
      await loadOrderData();

    } catch (error) {
      showError('発注の更新に失敗しました: ' + error.message);
    }
  }

  // 編集キャンセル
  function cancelEdit() {
    const createBtn = container.querySelector('#create-order-btn');
    const updateBtn = container.querySelector('#update-order-btn');
    const cancelBtn = container.querySelector('#cancel-edit-btn');

    if (createBtn) createBtn.style.display = 'inline-block';
    if (updateBtn) updateBtn.style.display = 'none';
    if (cancelBtn) cancelBtn.style.display = 'none';

    // フォームをクリア
    container.querySelector('#product-select').value = '';
    container.querySelector('#store-select').value = '';
    container.querySelector('#order-quantity').value = '';
    container.querySelector('#order-date').value = '';
  }

  // 発注削除
  async function deleteOrder(orderId) {
    try {
      if (!confirm('この発注を削除しますか？')) return;

      await window.aivicApi.delete(ORDER_TABLE, orderId);
      showSuccess('発注を削除しました');

      // データを再読み込み
      await loadOrderData();

    } catch (error) {
      showError('発注の削除に失敗しました: ' + error.message);
    }
  }

  // 一括削除
  async function bulkDeleteOrders() {
    try {
      if (selectedOrders.length === 0) {
        showError('削除する発注を選択してください');
        return;
      }

      if (!confirm(`選択した${selectedOrders.length}件の発注を削除しますか？`)) return;

      for (const orderId of selectedOrders) {
        await window.aivicApi.delete(ORDER_TABLE, orderId);
      }

      showSuccess(`${selectedOrders.length}件の発注を削除しました`);
      selectedOrders = [];

      // データを再読み込み
      await loadOrderData();

    } catch (error) {
      showError('一括削除に失敗しました: ' + error.message);
    }
  }

  // 店舗・商品マスタを読み込み
  async function loadMasterData() {
    try {
      // 店舗マスタを読み込み
      const stores = await window.aivicApi.list(STORES_TABLE);
      const storeSelect = container.querySelector('#store-select');
      if (storeSelect) {
        storeSelect.innerHTML = '<option value="">全店舗</option>';
        stores.forEach(store => {
          const option = document.createElement('option');
          option.value = store.id;
          option.textContent = store.name;
          storeSelect.appendChild(option);
        });
      }

      // 商品マスタを読み込み
      const products = await window.aivicApi.list(PRODUCTS_TABLE);
      const productSelect = container.querySelector('#product-select');
      if (productSelect) {
        productSelect.innerHTML = '<option value="">商品を選択</option>';
        products.forEach(product => {
          const option = document.createElement('option');
          option.value = product.id;
          option.textContent = product.name;
          productSelect.appendChild(option);
        });
      }

      currentProducts = products;

    } catch (error) {
      showError('マスタデータの読み込みに失敗しました: ' + error.message);
    }
  }

  // イベントリスナーを設定
  function setupEventListeners() {
    // 検索ボタン
    const searchBtn = container.querySelector('#search-orders-btn');
    if (searchBtn) {
      searchBtn.addEventListener('click', loadOrderData);
    }

    // 新規作成ボタン
    const createBtn = container.querySelector('#create-order-btn');
    if (createBtn) {
      createBtn.addEventListener('click', createOrder);
    }

    // 更新ボタン
    const updateBtn = container.querySelector('#update-order-btn');
    if (updateBtn) {
      updateBtn.addEventListener('click', updateOrder);
    }

    // キャンセルボタン
    const cancelBtn = container.querySelector('#cancel-edit-btn');
    if (cancelBtn) {
      cancelBtn.addEventListener('click', cancelEdit);
    }

    // 一括削除ボタン
    const bulkDeleteBtn = container.querySelector('#bulk-delete-btn');
    if (bulkDeleteBtn) {
      bulkDeleteBtn.addEventListener('click', bulkDeleteOrders);
    }

    // 全選択チェックボックス
    const selectAllCheckbox = container.querySelector('#select-all-orders');
    if (selectAllCheckbox) {
      selectAllCheckbox.addEventListener('change', (e) => {
        const checkboxes = container.querySelectorAll('.order-checkbox');
        checkboxes.forEach(cb => {
          cb.checked = e.target.checked;
        });
        updateSelectedOrders();
      });
    }

    // 日付バリデーション
    const dateInputs = container.querySelectorAll('#date-start, #date-end');
    dateInputs.forEach(input => {
      input.addEventListener('change', validateDateRange);
    });
  }

  // 初期化
  async function initialize() {
    try {
      await loadMasterData();
      setupEventListeners();

      // 今日の日付を設定
      const today = new Date().toISOString().split('T')[0];
      const startDateInput = container.querySelector('#date-start');
      const endDateInput = container.querySelector('#date-end');

      if (startDateInput && !startDateInput.value) {
        startDateInput.value = today;
      }
      if (endDateInput && !endDateInput.value) {
        endDateInput.value = today;
      }

    } catch (error) {
      showError('初期化に失敗しました: ' + error.message);
    }
  }

  // 初期化実行
  initialize();
}
